 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Grid lines partition the canvas into cells. Within each adjacent pair of
    # cells, the motif is horizontally reflected; when one cell is empty, copy
    # the reflected motif into it. When both are populated, the left cell is
    # the reference and the right cell is corrected to its reflection.
    row_seps = [r for r in range(h) if g[r] and g[r][0] != 0 and all(v == g[r][0] for v in g[r])]
    col_seps = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]

    def bands(n, seps):
        bounds = [-1] + seps + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds)-1)
                if bounds[i] + 1 < bounds[i + 1]]

    rbands = bands(h, row_seps)
    cbands = bands(w, col_seps)

    def motif(r0, r1, c0, c1):
        return [(r-r0, c-c0, g[r][c]) for r in range(r0, r1) for c in range(c0, c1)
                if g[r][c] != 0]

    def reflect_into(src, dst_bounds, row_bounds, src_width):
        d0, d1 = dst_bounds
        r0, r1 = row_bounds
        # Clear destination non-background cells, then place reflected source.
        for r in range(r0, r1):
            for c in range(d0, d1):
                if g[r][c] != 0:
                    g[r][c] = 0
        for y, x, color in src:
            r = r0 + y
            c = d0 + (src_width - 1 - x)
            if r0 <= r < r1 and d0 <= c < d1:
                g[r][c] = color

    for r0, r1 in rbands:
        j = 0
        while j + 1 < len(cbands):
            left, right = cbands[j], cbands[j+1]
            lm = motif(r0, r1, left[0], left[1])
            rm = motif(r0, r1, right[0], right[1])
            if lm:
                src = lm
                reflect_into(src, right, (r0, r1), left[1]-left[0])
            elif rm:
                # Symmetric case: only the right-hand tile contains the motif.
                src = rm
                reflect_into(src, left, (r0, r1), right[1]-right[0])
            j += 2
    return g
